(function(){const RA=globalThis.RA,D=(l,p)=>RA.D(l,p),E=(origin,prefix,root,suffix,source)=>({origin,prefix,root,suffix,source}),C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:"authored"}),M=(errorType,wrong,right,reason)=>({errorType,wrong,right,reason}),Q=(id,senseId,type,prompt,options,answer,explain,errorType)=>({id,senseId,type,prompt,options,answer,explain,errorType});
D("patch",{etymology:E("The clothing sense entered Middle English as pacche in the late fourteenth century; its origin is obscure, perhaps related to Old North French pieche, so no secure root is claimed.",null,null,null,"Etymonline, patch (https://www.etymonline.com/word/patch)."),contexts:[C("patch.s1","服饰","Grandma sewed a blue patch over the tear in my jacket before our camping trip.","露營旅行前，奶奶在我外套的破洞上縫了一塊藍色補片。","A patch is material sewn or stuck over a hole.","Sewed a patch over names the repair; before gives the deadline.","The cloth piece covers the tear in the jacket."),C("patch.s2","通用","A small patch of sunlight fell across the desk when the clouds moved apart.","雲散開時，一小片陽光落在書桌上。","A patch can be a small area different from what surrounds it.","Patch of sunlight names a bounded bright area; when gives its timing.","The lit area differs from the surrounding shade."),C("patch.s3","通用","They patched the leaking canvas with a square of waterproof fabric.","他們用一塊方形防水布修補漏水的帆布。","To patch means cover a hole or weak area with a patch.","Patched is a transitive verb with canvas as object; with introduces the material.","The added cloth seals the damaged area."),C("patch.s4","计算机","Install the security patch before reconnecting the laptop to the office network.","在把筆電重新連上辦公室網路前，先安裝安全修補程式。","A software patch is a small code update that corrects a program or security flaw.","Install is an imperative; before sets the required order.","The code update fixes a weakness before network access resumes.")],mistakes:[M("meaning","The technician called an update a patch even though it added no code, fixed no defect, and changed nothing in the program.","The technician called the small code update a patch because it fixed a defect in the program.","A software patch corrects or improves existing code; an update that changes nothing is not a patch.")],quiz:[Q("patch.q1","patch.s1","meaning","A cloth patch on a jacket is used to ___.",["cover a hole or worn area","measure the sleeve length","make the fabric transparent"],"cover a hole or worn area","The noun is a piece of material attached over damage.","meaning"),Q("patch.q2","patch.s2","context","Which is a patch of color?",["A small green area in an otherwise brown field","The entire field viewed from a plane","A uniform brown field with no variation"],"A small green area in an otherwise brown field","The small area contrasts with its surroundings.","context"),Q("patch.q3","patch.s4","meaning","A software patch is usually ___.",["a small code fix or correction","a fabric square sewn onto clothing","a full replacement computer"],"a small code fix or correction","This computing sense names a limited program update.","meaning"),Q("patch.q4","patch.s3","verb-form","Choose the past form: “They ____ the hole in the tent.”",["patched","patch","patching"],"patched","The regular past form adds -ed.","verb-form")]});
D("patchiness",{etymology:E("Formed from patchy + -ness; patchy derives from patch + -y, and the abstract noun describes uneven occurrence, quality, or distribution.",null,"patch","-iness","Etymonline, patchy (https://www.etymonline.com/word/patchy)."),contexts:[C("patchiness.s1","通用","The patchiness of the fog made driving difficult: some bends were clear, while others disappeared completely.","霧氣分布不均使駕駛變得困難：有些彎道清晰可見，有些卻完全被遮住。","Patchiness is uneven distribution or quality, with some areas differing from others.","The patchiness of the fog is the cause; the colon introduces contrasting locations.","Visibility changes from one stretch of road to another.")],mistakes:[M("meaning","The patchiness of the paint was clear because every wall had exactly the same shade and smooth coverage.","The uniformity of the paint was clear because every wall had the same shade and smooth coverage.","Patchiness means uneven or spotty quality; identical smooth coverage is uniform.")],quiz:[Q("patchiness.q1","patchiness.s1","meaning","Patchiness in a data set means ___.",["uneven quality or distribution","every value is identical","all observations are missing"],"uneven quality or distribution","The noun describes variation across portions of a whole.","meaning"),Q("patchiness.q2","patchiness.s1","context","Which weather report describes patchiness?",["Fog is thick in some valleys but absent on nearby hills.","Fog covers the entire region equally.","No fog is present anywhere."],"Fog is thick in some valleys but absent on nearby hills.","The fog is unevenly distributed across locations.","context"),Q("patchiness.q3","patchiness.s1","word-formation","The noun from patchy is ___.",["patchiness","patchly","patchinessesly"],"patchiness","The suffix -ness forms the abstract noun.","word-formation"),Q("patchiness.q4","patchiness.s1","word-choice","Reviewers noted the ____ of the translation, strong in some chapters and weak in others.",["patchiness","paternity","pastime"],"patchiness","Uneven quality across chapters is patchiness.","word-choice")]});
D("patchwork",{etymology:E("A compound of patch + work; it first referred to sewing scraps together and also developed a figurative sense for a whole made from mismatched parts.",null,"patch + work",null,"Etymonline, patchwork (https://www.etymonline.com/word/patchwork)."),contexts:[C("patchwork.s1","通用","The quilt was a patchwork of cotton squares saved from the family’s old clothes.","這床被子是用家人舊衣留下的棉布方片拼縫而成。","Patchwork is needlework made by stitching fabric scraps together, or a whole made of mismatched pieces.","A patchwork of cotton squares names its composition; saved modifies the scraps.","The quilt joins separate fabric pieces into one surface.")],mistakes:[M("meaning","The proposal was a patchwork of identical rules written as one consistent plan, with no pieces added from different sources.","The proposal was a unified plan rather than a patchwork because it used one consistent set of rules.","Patchwork suggests assorted pieces joined together, often without full consistency; the described plan is uniform.")],quiz:[Q("patchwork.q1","patchwork.s1","meaning","A patchwork quilt is made from ___.",["pieces of fabric stitched together","one uncut sheet of metal","a single block of carved stone"],"pieces of fabric stitched together","The literal sense joins cloth scraps into a larger piece.","meaning"),Q("patchwork.q2","patchwork.s1","context","Which policy might be called a patchwork?",["A collection of rules from different sources that do not fit smoothly","One consistent rule written for the whole system","A blank page with no policies"],"A collection of rules from different sources that do not fit smoothly","The figurative sense is a whole assembled from mismatched parts.","context"),Q("patchwork.q3","patchwork.s1","word-formation","A quilt sewn from scraps is a kind of ___.",["patchwork","patchiness","patcher"],"patchwork","The compound names work made by joining patches.","word-formation"),Q("patchwork.q4","patchwork.s1","meaning","A patchwork solution may be criticized because it is ___.",["made from disconnected or mismatched pieces","a single flawless unit","completely unrelated to any parts"],"made from disconnected or mismatched pieces","The figurative sense can imply an unevenly assembled whole.","meaning")]});
D("patchy",{etymology:E("Formed from patch + -y; the adjective first meant full of patches and now describes uneven distribution or quality.",null,"patch","-y","Etymonline, patchy (https://www.etymonline.com/word/patchy)."),contexts:[C("patchy.s1","通用","Patchy clouds allowed brief views of the moon, but other parts of the sky remained covered.","雲層分布不均，月亮偶爾露出來，但天空其他部分仍被遮住。","Patchy means occurring in some areas but not others.","Attributive adjective before clouds; but contrasts the clear and covered areas.","The cloud cover is scattered rather than continuous."),C("patchy.s2","通用","The team’s patchy first-half defense improved after the coach changed the formation.","教練改變陣形後，球隊上半場時好時壞的防守有所改善。","Patchy can mean good in some parts and poor in others.","Attributive adjective before defense; after gives when it improved.","The defense did not perform consistently throughout the half.")],mistakes:[M("meaning","Her patchy attendance was perfectly consistent: she came to every session without missing one.","Her regular attendance was perfectly consistent: she came to every session without missing one.","Patchy means inconsistent or intermittent; attending every session is regular, not patchy.")],quiz:[Q("patchy.q1","patchy.s1","meaning","Patchy rain falls ___.",["in some places but not others","at the same rate everywhere","only beneath the ground"],"in some places but not others","Patchy describes uneven spatial distribution.","meaning"),Q("patchy.q2","patchy.s2","context","Which performance is patchy?",["Excellent in some sections but weak in others","Equally strong from beginning to end","Not attempted at all"],"Excellent in some sections but weak in others","This sense describes uneven quality.","context"),Q("patchy.q3","patchy.s1","grammar","Choose the adjective: “The radio signal was ____ in the mountains.”",["patchy","patchiness","patchily"],"patchy","The adjective follows was and describes the signal.","grammar"),Q("patchy.q4","patchy.s2","word-choice","The report’s evidence was ____: detailed in one section and thin in the next.",["patchy","patent","paternal"],"patchy","The uneven quality of evidence is patchy.","word-choice")]});
D("patent",{etymology:E("From Anglo-French lettre patent, literally an ‘open letter’, from Latin patentem, present participle of patere ‘lie open’; the noun became an official grant of exclusive rights, while related adjective senses mean protected or obvious.",null,"patere","-ent","Etymonline, patent (https://www.etymonline.com/word/patent)."),contexts:[C("patent.s1","法律","The inventor received a patent that prevents competitors from copying the filter for the stated term.","發明人取得一項專利，在規定期限內禁止競爭者仿製該濾水器。","A patent is an official right that prevents others from copying an invention for a set time.","Received a patent is the action; that clause explains its protection.","The grant gives a time-limited exclusive right over the invention."),C("patent.s2","商业","The company sells a patented valve whose design is protected until the patent expires.","公司販售一種有專利保護的閥門，其設計在專利到期前受到保護。","Patent as an adjective means protected by a patent or made by a patented process.","Attributive adjective before valve; whose clause explains the protection.","The design is protected from copying for the term of its grant."),C("patent.s3","书面","It was a patent error to label the north entrance as an emergency exit when it opened onto a locked wall.","把通往封閉牆面的北門標成緊急出口，顯然是個錯誤。","Patent as an adjective can mean clear and obvious.","Attributive adjective before error; when introduces the evidence.","The locked wall makes the labeling mistake unmistakable."),C("patent.s4","法律","The engineer patented her low-cost filter after completing the required application.","完成必要申請後，工程師為她的低成本濾水器取得了專利。","To patent means obtain a patent for an invention.","Patented is a transitive past-tense verb; after gives sequence.","The application results in official protection for the invention.")],mistakes:[M("meaning","The inventor’s patent gave competitors unlimited permission to copy the design immediately without restriction.","The inventor’s patent gave the inventor an exclusive right to prevent competitors from copying the design for a set term.","A patent grants time-limited exclusive rights; it does not give competitors unrestricted permission.")],quiz:[Q("patent.q1","patent.s1","meaning","A patent gives an inventor ___.",["time-limited exclusive rights over an invention","automatic ownership of every similar idea forever","permission to ignore every safety rule"],"time-limited exclusive rights over an invention","The legal right prevents copying for a defined term.","meaning"),Q("patent.q2","patent.s2","context","Which item is patented?",["A tool protected by an active invention right","A common tool with no protected design","A tool borrowed for one afternoon"],"A tool protected by an active invention right","The adjective means protected under a patent.","context"),Q("patent.q3","patent.s3","meaning","A patent mistake is one that is ___.",["obvious","secret and impossible to detect","legally registered"],"obvious","Patent can mean clear and unmistakable.","meaning"),Q("patent.q4","patent.s4","verb-form","Choose the verb: “The company hopes to ____ its new pump.”",["patent","patented","patenting"],"patent","To after hopes takes the base verb.","verb-form")]});
D("patently",{etymology:E("Formed from patent in its sense ‘obvious’ + -ly; patently means so clearly or obviously that reasonable doubt is absent.",null,"patent","-ly","Merriam-Webster, patently (https://www.merriam-webster.com/dictionary/patently); Etymonline, patent (https://www.etymonline.com/word/patent)."),contexts:[C("patently.s1","通用","The claim was patently false because the signed record showed that the meeting had never taken place.","這項說法顯然不實，因為簽署紀錄顯示會議根本沒有舉行。","Patently means so obviously that no reasonable doubt remains.","Adverb modifies false; because supplies decisive evidence.","The record directly contradicts the claim.")],mistakes:[M("meaning","The result was patently uncertain even though every measurement matched exactly and no alternative explanation remained.","The result was patently clear because every measurement matched exactly and no alternative explanation remained.","Evidence with no reasonable alternative makes a result obvious rather than uncertain.")],quiz:[Q("patently.q1","patently.s1","meaning","A patently false statement is ___.",["obviously untrue","difficult to evaluate","guaranteed to be accurate"],"obviously untrue","Patently means clearly or unmistakably.","meaning"),Q("patently.q2","patently.s1","context","Which claim is patently wrong?",["It says the sun rose at midnight, while records show noon daylight.","It reports a measurement matching all available records.","It asks for more evidence before deciding."],"It says the sun rose at midnight, while records show noon daylight.","The available evidence makes the claim plainly false.","context"),Q("patently.q3","patently.s1","grammar","Choose the adverb: “The excuse was ____ implausible.”",["patently","patent","patentable"],"patently","The adverb modifies implausible.","grammar"),Q("patently.q4","patently.s1","word-choice","The label was ____ misleading because it named the wrong ingredient.",["patently","paternal","pathway"],"patently","The evidence makes the misleading label obvious.","word-choice")]});
D("paternal",{etymology:E("From Old French paternal and Latin paternalis, based on paternus ‘of a father’ and pater ‘father’; it means related to or coming from the father, or fatherly in manner.",null,"pater","-nal","Etymonline, paternal (https://www.etymonline.com/word/paternal)."),contexts:[C("paternal.s1","亲属","Her paternal relatives kept family records on her father’s side for four generations.","她父親那一側的親屬保存了四代的家族紀錄。","Paternal means of or from the father, including the father’s side of a family.","Attributive adjective before relatives; on her father’s side clarifies the relation.","These relatives belong to the family line through her father."),C("paternal.s1","亲属","The coach’s paternal concern was clear when he checked that every young player had a safe ride home.","教練關懷孩子般的照料很明顯，他確認每位年輕球員都能安全回家。","Paternal can also describe care or authority resembling a father’s.","Attributive adjective before concern; when gives evidence of that care.","The coach takes protective responsibility for the young players.")],mistakes:[M("meaning","Her paternal aunt was related to her only through her mother’s family, with no connection to her father.","Her maternal aunt was related to her through her mother’s family, with no connection to her father.","Paternal refers to the father’s side; a relative connected only through the mother is maternal.")],quiz:[Q("paternal.q1","paternal.s1","meaning","A paternal grandfather is the father of someone’s ___.",["father","mother’s sister","spouse’s cousin"],"father","Paternal identifies the father’s side of a family.","meaning"),Q("paternal.q2","paternal.s1","context","Which action shows paternal care?",["An adult checks that a child gets home safely.","A clerk stamps a receipt without speaking.","A stranger ignores a child in danger."],"An adult checks that a child gets home safely.","Protective guidance can be described as paternal.","context"),Q("paternal.q3","paternal.s1","word-choice","She traced the inheritance through her ____ line.",["paternal","patently","patient"],"paternal","The inheritance came through her father’s family.","word-choice"),Q("paternal.q4","paternal.s1","meaning","A paternal relative is connected through the ___.",["father’s side","mother’s side only","unrelated neighbors"],"father’s side","Paternal means belonging to or coming from a father.","meaning")]});
D("paternity",{etymology:E("From Old French paternité and Late Latin paternitas, based on Latin paternus ‘of a father’; paternity is the state or legal/biological relation of being a father.",null,"paternus","-ity","Etymonline, paternity (https://www.etymonline.com/word/paternity)."),contexts:[C("paternity.s1","法律","The court ordered a paternity test before deciding who should be listed as the child’s legal father.","法院在決定誰應列為孩子的法律父親前，下令進行親子鑑定。","Paternity is the state of being a father, especially in law or biology.","Ordered a paternity test is the action; before marks the decision sequence.","The test supplies evidence about biological fatherhood for a legal matter.")],mistakes:[M("meaning","The paternity test established that the woman was the child’s biological mother and identified no possible father.","The maternity test established that the woman was the child’s biological mother and identified no possible father.","Paternity concerns fatherhood; maternity concerns motherhood.")],quiz:[Q("paternity.q1","paternity.s1","meaning","Paternity is the state or relation of being a ___.",["father","sibling","medical patient"],"father","The noun concerns fatherhood.","meaning"),Q("paternity.q2","paternity.s1","context","When might a court review paternity?",["When determining a child’s legal father","When deciding who owns a restaurant","When recording a patient’s temperature"],"When determining a child’s legal father","The legal question concerns the father–child relation.","context"),Q("paternity.q3","paternity.s1","word-formation","The noun for fatherhood is ___.",["paternity","paternal","patiently"],"paternity","The suffix -ity forms an abstract noun from paternal.","word-formation"),Q("paternity.q4","paternity.s1","word-choice","The laboratory conducted a ____ test to assess biological fatherhood.",["paternity","patience","pathology"],"paternity","A paternity test investigates the father–child biological relation.","word-choice")]});
D("path",{etymology:E("From Old English paþ, a narrow route across land; its deeper origin is uncertain, and proposed Iranian links remain disputed, so no root is asserted.",null,null,null,"Etymonline, path (https://www.etymonline.com/word/path)."),contexts:[C("path.s1","地理","A muddy path wound through the orchard and ended at a gate beside the river.","一條泥濘小徑蜿蜒穿過果園，終點是河邊的柵門。","A path is a narrow track made for walking or worn by walkers.","Wound through and ended at describe the route and endpoint.","It is a narrow walking track across the land."),C("path.s2","通用","The satellite followed a curved path around Earth before entering its final orbit.","衛星先沿著地球周圍的彎曲軌跡飛行，再進入最終軌道。","A path is the line along which a person, vehicle, or object moves.","Followed a path describes motion; before marks the next phase.","The satellite travels along a defined trajectory."),C("path.s3","通用","An apprenticeship gave him a path into electrical work without requiring a four-year degree.","學徒訓練為他進入電工行業提供了一條途徑，不必先取得四年制學位。","A path can be a way of life or actions leading toward a goal.","Gave him a path into expresses opportunity; without contrasts a requirement avoided.","The apprenticeship provides a sequence toward a career goal.")],mistakes:[M("meaning","The hikers followed a path by remaining inside their cabin all day and never walking outside.","The hikers stayed inside their cabin all day and did not follow a path outdoors.","A path is a route people can walk; staying indoors without traveling does not follow one.")],quiz:[Q("path.q1","path.s1","meaning","A forest path is ___.",["a narrow route for walking","a wide ocean current","a locked room in a house"],"a narrow route for walking","The physical sense is a walking track.","meaning"),Q("path.q2","path.s2","context","Which object follows a path through space?",["A satellite moving along an orbit","A fixed statue that never moves","A page stored in a drawer"],"A satellite moving along an orbit","The path is the trajectory of a moving object.","context"),Q("path.q3","path.s3","meaning","A path into a career is ___.",["a route of steps that can lead to that job","a walking trail through a park only","a list of unrelated hobbies"],"a route of steps that can lead to that job","The figurative sense is a sequence toward a goal.","meaning"),Q("path.q4","path.s1","word-choice","A marked ____ led the campers from the lake to the shelter.",["path","paternity","patience"],"path","The walking route is a path.","word-choice")]});
D("pathetic",{etymology:E("From Greek pathetikos ‘subject to feeling, capable of emotion’, via Late Latin and French; it first meant emotionally moving, then came to mean pitiful or, colloquially, very inadequate.",null,"pathetikos","-ic","Etymonline, pathetic (https://www.etymonline.com/word/pathetic)."),contexts:[C("pathetic.s1","书面","The final letter was pathetic in its quiet description of the sailor’s last visit home.","最後一封信以平靜的筆觸描寫水手最後一次回家，令人感到悲憫。","Pathetic can mean causing pity or sadness.","Attributive adjective before letter; in its description gives the source of feeling.","The account of a final visit evokes sympathy and sadness."),C("pathetic.s2","口语","The team’s pathetic attempt to repair the roof failed when its only tool broke immediately.","這支隊伍修屋頂的拙劣嘗試，在唯一工具立刻壞掉時宣告失敗。","Colloquially, pathetic means very weak, unsuccessful, or inadequate.","Attributive adjective before attempt; when introduces the failure.","The effort lacks the tools and competence needed to succeed.")],mistakes:[M("meaning","The rescue was pathetic because it saved every person quickly and left no one in danger or distress.","The rescue was successful because it saved every person quickly and left no one in danger or distress.","A successful rescue that removes danger is not pathetic in the sense of inadequate or pitiable.")],quiz:[Q("pathetic.q1","pathetic.s1","meaning","A pathetic story may make a reader feel ___.",["pity or sadness","mathematical certainty","hunger for no reason"],"pity or sadness","The older sense is emotionally moving and pitiful.","meaning"),Q("pathetic.q2","pathetic.s2","context","Which effort is pathetic in the informal sense?",["A flimsy repair that fails at once","A careful repair that holds for years","A plan completed successfully"],"A flimsy repair that fails at once","The attempt is very weak and unsuccessful.","context"),Q("pathetic.q3","pathetic.s1","grammar","Choose the adjective: “The scene was deeply ____.”",["pathetic","pathetically","pathos"],"pathetic","The predicate after was requires an adjective.","grammar"),Q("pathetic.q4","pathetic.s2","word-choice","The excuse was ____: it did not explain the missing work at all.",["pathetic","pathogen","paternal"],"pathetic","The excuse is inadequate and unconvincing.","word-choice")]});
D("pathfinder",{etymology:E("A compound of path + finder, recorded in the nineteenth century for someone who discovers a route or leads the way; figuratively it can mean a pioneer in research or policy.",null,"path + find","-er","Etymonline, pathfinder (https://www.etymonline.com/word/pathfinder)."),contexts:[C("pathfinder.s1","通用","The pathfinder tested a route through the canyon before the larger expedition set out.","探路者在大隊探險隊出發前，先測試了一條穿越峽谷的路線。","A pathfinder is someone who discovers a route or leads the way.","Tested a route describes the task; before sets the sequence.","The scout identifies a safe way for the group to follow.")],mistakes:[M("meaning","The expedition called the pathfinder the person who refused to explore, waited at home, and never helped identify a route.","The expedition called the pathfinder the person who explored ahead and identified a route for others.","A pathfinder leads or discovers a way; refusing to explore is the opposite role.")],quiz:[Q("pathfinder.q1","pathfinder.s1","meaning","A pathfinder helps others by ___.",["discovering a route or leading the way","closing every trail","waiting at the destination without exploring"],"discovering a route or leading the way","The compound describes someone who finds a path.","meaning"),Q("pathfinder.q2","pathfinder.s1","context","Which scientist could be called a pathfinder?",["One who opens a new research approach for others","One who copies a textbook without testing anything","One who abandons the field before beginning"],"One who opens a new research approach for others","The figurative sense is a pioneer who leads in a field.","context"),Q("pathfinder.q3","pathfinder.s1","word-formation","A person who finds the route ahead is a ___.",["pathfinder","pathfindingness","pathway"],"pathfinder","The agent noun uses find + -er in the compound.","word-formation"),Q("pathfinder.q4","pathfinder.s1","word-choice","The guide went first through the unmapped forest as a ____ for the group.",["pathfinder","patient","patchwork"],"pathfinder","The guide discovers the route for those following.","word-choice")]});
D("pathogen",{etymology:E("Recorded in the nineteenth century as a back-formation from pathogenic; that adjective combines Greek pathos ‘disease, suffering’ with a form meaning ‘producing’.",null,"pathos + -genic",null,"Etymonline, pathogen (https://www.etymonline.com/word/pathogen)."),contexts:[C("pathogen.s1","科学","The lab isolated a pathogen from the water sample and tested whether it could cause illness in mice.","實驗室從水樣中分離出一種病原體，並測試它是否會使老鼠生病。","A pathogen is a germ or microorganism that causes disease.","Isolated a pathogen is the action; whether introduces the test question.","The researchers investigate whether the microbe can produce disease.")],mistakes:[M("meaning","The vaccine was designed to eliminate every pathogen, but the organisms in the sample were harmless and caused no disease.","The vaccine was designed to target pathogens, but the organisms in the sample were harmless and caused no disease.","A pathogen causes disease; harmless organisms that cause no illness are not pathogens.")],quiz:[Q("pathogen.q1","pathogen.s1","meaning","A pathogen is an organism that ___.",["can cause disease","always improves digestion","turns sunlight into electricity"],"can cause disease","Pathogen means a disease-causing germ or microorganism.","meaning"),Q("pathogen.q2","pathogen.s1","context","Which sample contains a pathogen?",["It contains a microbe shown to cause infection.","It contains sterile water only.","It contains harmless fibers that cause no illness."],"It contains a microbe shown to cause infection.","The organism is linked to disease.","context"),Q("pathogen.q3","pathogen.s1","word-formation","A disease-causing microorganism is a ___.",["pathogen","pathway","pathos"],"pathogen","The word names an agent that produces disease.","word-formation"),Q("pathogen.q4","pathogen.s1","meaning","Why do public-health labs monitor pathogens?",["They may spread disease.","They are all harmless pieces of dust.","They measure road distances."],"They may spread disease.","Pathogens matter because they can cause illness.","meaning")]});
D("pathological",{etymology:E("Formed from pathologic + -al, ultimately from pathology; the adjective first meant related to disease and later gained a figurative sense for extreme, illness-like behavior.",null,"pathology","-al","Etymonline, pathological (https://www.etymonline.com/word/pathological)."),contexts:[C("pathological.s1","通用","The scan showed a pathological change in the tissue that required review by a specialist.","掃描顯示組織出現病理變化，需要專科醫師評估。","Pathological means connected with pathology or caused by disease.","Attributive adjective before change; that clause gives the follow-up need.","The tissue change is associated with disease and requires medical interpretation."),C("pathological.s2","通用","His pathological fear of elevators kept him from entering even an empty lift in a low building.","他對電梯的病態恐懼，使他連低樓裡空著的電梯也不敢進。","Figuratively, pathological describes an extreme, unreasonable behavior resembling illness.","Attributive adjective before fear; kept him from explains its effect.","The fear is so extreme that it interferes with ordinary life.")],mistakes:[M("meaning","Her pathological habit was a harmless preference she controlled easily and that never caused distress or disruption.","Her mild preference was harmless and easily controlled, causing no distress or disruption.","Pathological describes an extreme or disease-like condition; a mild, controlled preference does not fit.")],quiz:[Q("pathological.q1","pathological.s1","meaning","A pathological finding is connected with ___.",["disease or the study of disease","a social celebration","a route through a forest"],"disease or the study of disease","The medical adjective relates to pathology.","meaning"),Q("pathological.q2","pathological.s2","context","Which fear might be called pathological figuratively?",["An extreme fear that prevents ordinary daily activities","A brief caution around a real hazard","A mild preference for one color"],"An extreme fear that prevents ordinary daily activities","The figurative sense describes unreasonable, illness-like excess.","context"),Q("pathological.q3","pathological.s1","grammar","Choose the adjective: “The doctor noted a ____ response in the tissue.”",["pathological","pathology","pathologically"],"pathological","The blank modifies response and requires an adjective.","grammar"),Q("pathological.q4","pathological.s2","word-choice","A ____ obsession can interfere with work and relationships.",["pathological","pastoral","patchy"],"pathological","The obsession is extreme and unreasonable.","word-choice")]});
D("pathology",{etymology:E("From French pathologie and medical Latin pathologia, from Greek pathos ‘suffering, disease’ + -logia ‘study’; it names both the science of disease and characteristic disease processes.",null,"pathos","-logy","Etymonline, pathology (https://www.etymonline.com/word/pathology)."),contexts:[C("pathology.s1","通用","She studied pathology to learn how infections damage organs and how tissue samples reveal disease.","她學習病理學，以了解感染如何損害器官，以及組織樣本如何顯示疾病。","Pathology is the scientific study of the causes and effects of disease.","Studied pathology is the action; to learn gives its purpose.","The field examines disease mechanisms and evidence in tissue."),C("pathology.s2","通用","The report described the pathology of the lung condition, including inflammation and progressive scarring.","報告描述了肺部疾病的病變過程，包括發炎和逐漸形成的疤痕。","Pathology can mean the typical features and processes of a particular disease.","Pathology of the condition names its disease process; including lists features.","Inflammation and scarring are characteristic changes of the condition.")],mistakes:[M("meaning","The pathology report described healthy tissue with no abnormal process, but called the normal sample a disease condition.","The pathology report found healthy tissue and no disease process in the sample.","Pathology in this sense concerns disease processes; normal tissue without abnormality is not itself a pathology.")],quiz:[Q("pathology.q1","pathology.s1","meaning","A pathology course studies ___.",["the causes and effects of disease","the design of garden patios","the history of political parties"],"the causes and effects of disease","Pathology is the scientific study of disease.","meaning"),Q("pathology.q2","pathology.s2","context","Which statement uses pathology to mean disease process?",["The pathology of the condition includes inflammation and tissue damage.","She enrolled in a pathology degree.","The lab hired a pathology professor."],"The pathology of the condition includes inflammation and tissue damage.","Here it names the characteristic disease changes.","context"),Q("pathology.q3","pathology.s1","word-formation","The scientific study of disease is ___.",["pathology","pathogenic","patience"],"pathology","The suffix -logy means the study of a subject.","word-formation"),Q("pathology.q4","pathology.s2","meaning","A report may discuss a disease’s pathology by describing ___.",["its typical changes and processes","the patient’s favorite hobby","the hospital’s parking map"],"its typical changes and processes","This sense is the pattern of disease features.","meaning")]});
D("pathos",{etymology:E("From Greek pathos ‘suffering, feeling, emotion, calamity’; in English rhetoric it names the quality in a story, scene, or voice that evokes pity or sorrow.",null,"pathos",null,"Etymonline, pathos (https://www.etymonline.com/word/pathos)."),contexts:[C("pathos.s1","文学","The film’s pathos came from the quiet reunion between the child and the parent who had searched for years.","電影令人悲憫的力量來自孩子與多年尋找他的家長之間那場安靜的重逢。","Pathos is a story or scene’s power to evoke pity or sorrow.","Pathos is the subject; from introduces its source.","The reunion combines separation and relief, moving the audience emotionally.")],mistakes:[M("meaning","The scene’s pathos made the audience feel no pity, sadness, or emotional response at all.","The scene’s coldness left the audience without pity, sadness, or emotional response.","Pathos is the power to evoke pity or sorrow; a scene that evokes no response lacks pathos.")],quiz:[Q("pathos.q1","pathos.s1","meaning","Pathos in a novel is its power to ___.",["evoke pity or sorrow","prove a mathematical theorem","list every character’s address"],"evoke pity or sorrow","The rhetorical term refers to an emotional appeal that moves the audience.","meaning"),Q("pathos.q2","pathos.s1","context","Which scene has pathos?",["A child quietly says goodbye to a parent leaving for a dangerous rescue.","A list of train times is read in a neutral voice.","A comic character slips on a banana peel."],"A child quietly says goodbye to a parent leaving for a dangerous rescue.","The separation and danger can arouse pity and sadness.","context"),Q("pathos.q3","pathos.s1","word-choice","The final letter gave the story emotional ____.",["pathos","pathway","paternity"],"pathos","The letter adds the power to evoke pity or sorrow.","word-choice"),Q("pathos.q4","pathos.s1","meaning","A speaker uses pathos to appeal to an audience’s ___.",["emotions and compassion","spelling rules only","sense of distance"],"emotions and compassion","Pathos is emotional appeal that can evoke pity.","meaning")]});
D("pathway",{etymology:E("A compound of path + way, recorded in the sixteenth century; it can name a narrow walking track or a sequence of actions or chemical steps leading to an outcome.",null,"path + way",null,"Etymonline, pathway (https://www.etymonline.com/word/pathway)."),contexts:[C("pathway.s1","通用","A stone pathway led from the back gate to the greenhouse.","一條石板小路從後門通往溫室。","A pathway is a narrow track for people to walk on.","Led from and to show the route’s endpoints.","The stones form a walking route between the gate and greenhouse."),C("pathway.s2","通用","The training program provides a pathway from an entry-level role to laboratory management.","培訓計畫提供一條從初階職位晉升到實驗室管理的途徑。","A pathway can be a series of actions or steps leading to a result.","Pathway from A to B names the progression; provides is the main verb.","The program offers a sequence toward a career goal.")],mistakes:[M("meaning","The training pathway led nowhere and contained no steps or actions that could move a learner toward the qualification.","The training pathway led to the qualification through a sequence of required courses.","A figurative pathway is a route of steps toward a result; a sequence with no progress does not lead to one.")],quiz:[Q("pathway.q1","pathway.s1","meaning","A garden pathway is ___.",["a narrow walking track","a secret word for entry","a type of medical germ"],"a narrow walking track","The physical sense is a route for people to walk.","meaning"),Q("pathway.q2","pathway.s2","context","Which is a pathway to a qualification?",["A sequence of courses and practice that leads to certification","A locked room with no training materials","A list of unrelated hobbies"],"A sequence of courses and practice that leads to certification","The figurative sense is a series of steps toward a result.","context"),Q("pathway.q3","pathway.s1","word-formation","A narrow route for walkers can be called a ___.",["pathway","pathos","pathology"],"pathway","The compound path + way names a walking route.","word-formation"),Q("pathway.q4","pathway.s2","meaning","A pathway through a process describes ___.",["steps that lead toward an outcome","a random event with no connection","an obstacle that stops every action"],"steps that lead toward an outcome","The figurative sense is a route through sequential actions.","meaning")]});
D("patience",{etymology:E("From Old French pacience and Latin patientia ‘endurance, the quality of bearing’; it is an abstract noun from patiens, the present participle of pati ‘endure, undergo’.",null,"pati","-ence","Etymonline, patience (https://www.etymonline.com/word/patience)."),contexts:[C("patience.s1","通用","The mechanic showed patience while the apprentice repeated the wiring test for the third time.","學徒第三次重做接線測試時，技工仍耐心等候。","Patience is the ability to accept delay, difficulty, or annoyance calmly.","Showed patience while introduces the test situation.","The mechanic remains calm despite repetition and delay.")],mistakes:[M("meaning","Her patience vanished as she waited calmly for hours, listened without irritation, and never complained.","Her patience held as she waited calmly for hours, listened without irritation, and never complained.","Calm endurance during a long wait demonstrates patience rather than its loss.")],quiz:[Q("patience.q1","patience.s1","meaning","Patience helps someone ___.",["remain calm during delay or difficulty","become angry at every small wait","avoid hearing any explanation"],"remain calm during delay or difficulty","The noun describes calm endurance.","meaning"),Q("patience.q2","patience.s1","context","Which person shows patience?",["A tutor calmly explains the same step again.","A driver shouts after waiting ten seconds.","A clerk refuses to listen to a question."],"A tutor calmly explains the same step again.","The tutor accepts repetition without irritation.","context"),Q("patience.q3","patience.s1","word-choice","Learning a difficult instrument takes time and ____.",["patience","paternity","pathos"],"patience","The learner needs calm persistence while improving.","word-choice"),Q("patience.q4","patience.s1","meaning","A patient person is likely to handle a delay ___.",["calmly","by panicking immediately","by blaming every bystander"],"calmly","Patience enables someone to accept delays without anger.","meaning")]});
D("patient",{etymology:E("From Old French pacient and Latin patientem ‘bearing, enduring, suffering’; English uses it as an adjective for calm endurance and as a noun for someone receiving medical care.",null,"pati","-ent","Etymonline, patient (https://www.etymonline.com/word/patient)."),contexts:[C("patient.s1","医学","The nurse explained the dosage to each patient before handing over the medicine.","護士在交付藥物前，向每位病患說明劑量。","A patient is a person receiving medical treatment.","To each patient identifies the recipients; before gives the order.","The people are being treated and need instructions for their medicine."),C("patient.s2","通用","Be patient with the new operator while she learns the control panel.","新操作員學習控制面板時，請對她多些耐心。","Patient as an adjective means able to wait or accept trouble without becoming angry.","Be patient with is an imperative adjective phrase; while gives the learning period.","The speaker asks others to tolerate the beginner’s learning time.")],mistakes:[M("meaning","The patient was the surgeon performing the operation, not the person receiving treatment.","The surgeon was the doctor performing the operation; the patient was the person receiving treatment.","A patient receives medical care; the surgeon provides it.")],quiz:[Q("patient.q1","patient.s1","meaning","In a clinic, a patient is ___.",["someone receiving medical care","the person who repairs the building","a medicine bottle"],"someone receiving medical care","The noun names a person under treatment.","meaning"),Q("patient.q2","patient.s2","context","Which instruction asks someone to be patient?",["Wait calmly while the technician finishes the repair.","Demand an answer before the question is heard.","Leave immediately whenever a task takes time."],"Wait calmly while the technician finishes the repair.","Patient as an adjective means accept delay without anger.","context"),Q("patient.q3","patient.s2","grammar","Choose the adjective: “Please be ____ while the child ties the laces.”",["patient","patiently","patience"],"patient","After be, the sentence needs the adjective patient.","grammar"),Q("patient.q4","patient.s1","word-choice","The doctor called the next ____ into the examination room.",["patient","patience","patio"],"patient","The person receiving medical care is the patient.","word-choice")]});
D("patients",{etymology:E("The regular plural of patient in its medical noun sense; patient came from Latin patientem ‘suffering, enduring’, referring to a person under medical treatment.",null,"pati","-s","Etymonline, patient (https://www.etymonline.com/word/patient)."),contexts:[C("patients.s1","健康","The clinic opened an extra room so patients with flu symptoms could wait apart from other visitors.","診所增開一間候診室，讓有流感症狀的病人與其他訪客分開等候。","Patients are people receiving medical care.","Patients is the subject; so introduces why the extra room opened.","The clinic separates people seeking care for possible infection.")],mistakes:[M("meaning","The clinic discharged all patients because everyone receiving treatment was a nurse providing care and no one was a patient.","The clinic discharged all patients because everyone receiving treatment had completed care and no longer needed admission.","A nurse provides care; a patient receives it. The original reverses those roles.")],quiz:[Q("patients.q1","patients.s1","meaning","Patients are people who ___.",["receive medical care","write laws in a parliament","repair the clinic’s roof"],"receive medical care","The plural noun refers to people under treatment.","meaning"),Q("patients.q2","patients.s1","context","Which group consists of patients?",["People waiting to see a doctor about their symptoms","Doctors preparing to examine them","Visitors delivering flowers but seeking no care"],"People waiting to see a doctor about their symptoms","They are seeking medical attention.","context"),Q("patients.q3","patients.s1","plural","Choose the plural of patient: “The ward has six ____.”",["patients","patientes","patient's"],"patients","Add -s to form the regular plural.","plural"),Q("patients.q4","patients.s1","word-choice","The hospital asked ____ to check in at the front desk.",["patients","paternal","pathos"],"patients","People receiving care check in as patients.","word-choice")]});
D("patio",{etymology:E("From Spanish patio, recorded in English in the early nineteenth century for an open inner court; the modern English sense is a paved outdoor terrace beside a building.",null,"patio",null,"Etymonline, patio (https://www.etymonline.com/word/patio)."),contexts:[C("patio.s1","家居","They placed two chairs on the patio so they could eat breakfast outside on sunny days.","他們在露台上放了兩張椅子，好在晴天到戶外吃早餐。","A patio is a paved area next to a house used for sitting outdoors.","On the patio locates the chairs; so introduces the purpose.","The paved outdoor area beside the house is used for sitting and eating.")],mistakes:[M("meaning","The patio was an indoor carpeted bedroom on the second floor with no outdoor access.","The patio was a paved outdoor sitting area beside the house.","A patio is an outdoor paved area; an indoor bedroom is not a patio.")],quiz:[Q("patio.q1","patio.s1","meaning","A patio is usually ___.",["a paved outdoor area beside a building","a narrow path through a forest","an indoor medical room"],"a paved outdoor area beside a building","The noun names an outdoor sitting area.","meaning"),Q("patio.q2","patio.s1","context","Which home feature is a patio?",["A paved terrace where people sit outside","A carpeted bedroom upstairs","A covered kitchen cupboard"],"A paved terrace where people sit outside","The terrace fits the outdoor paved sense.","context"),Q("patio.q3","patio.s1","word-choice","They carried lunch outside and ate on the ____ beside the house.",["patio","pathogen","passbook"],"patio","The paved outdoor area is the patio.","word-choice"),Q("patio.q4","patio.s1","meaning","Why might chairs be placed on a patio?",["So people can sit outdoors near the house","To store them under the floor","To use them as a garden path"],"So people can sit outdoors near the house","Patios are outdoor areas used for sitting.","meaning")]});
})();
